//! Generated vanilla registry data used for build-time validation of world
//! resources (issue #317 §3.4, made version-aware by issue #356).
//!
//! [`VANILLA_BIOMES`] is generated by `sand-build`'s codegen pipeline
//! (`sand-build/src/codegen/biomes.rs`) from the real Minecraft data
//! generator's `biome_parameters` reports, the same download/cache
//! infrastructure `sand_core::generated::{Item, Block, EntityType,
//! SoundEvent}` already use — not a hand-maintained list. Like every other
//! generated registry in this crate, it reflects whichever Minecraft
//! version `sand-core` itself was compiled against (`SAND_MC_VERSION`,
//! defaulting to `sand_version::DEFAULT_CODEGEN_VERSION`) — recorded
//! exactly as [`CODEGEN_MINECRAFT_VERSION`], not merely assumed to equal
//! the default constant (a project can override `SAND_MC_VERSION`). See
//! [`super::validate::validate_for_context`] for how a build targeting a
//! *different* version is handled.
//!
//! Only `minecraft:`-namespaced references are checked against this list —
//! a custom mod or datapack biome (any other namespace) is accepted
//! unconditionally, since Sand cannot know about registry content it
//! didn't generate.

include!(concat!(env!("OUT_DIR"), "/biomes.rs"));

/// Whether `path` (without the `minecraft:` namespace prefix) is a known
/// vanilla biome for the Minecraft version `sand-core` was compiled
/// against. Only meaningful for `minecraft:`-namespaced references — see
/// the module docs.
pub(crate) fn is_known_vanilla_biome(path: &str) -> bool {
    VANILLA_BIOMES.contains(&format!("minecraft:{path}").as_str())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn recognizes_common_biomes() {
        assert!(is_known_vanilla_biome("plains"));
        assert!(is_known_vanilla_biome("the_end"));
    }

    #[test]
    fn rejects_a_misspelled_biome() {
        assert!(!is_known_vanilla_biome("dessert"));
        assert!(!is_known_vanilla_biome("plainss"));
    }

    #[test]
    fn generated_list_is_non_empty_and_has_no_duplicates() {
        // A real codegen run always includes at least the five fixed End
        // biomes (see biomes.rs's module docs), so an empty list here means
        // codegen silently produced nothing -- fail loudly instead.
        assert!(
            !VANILLA_BIOMES.is_empty(),
            "generated VANILLA_BIOMES is empty; codegen may have failed silently"
        );
        let mut sorted = VANILLA_BIOMES.to_vec();
        sorted.sort_unstable();
        sorted.dedup();
        assert_eq!(sorted.len(), VANILLA_BIOMES.len());
    }

    #[test]
    fn generated_list_includes_the_fixed_end_biomes() {
        for end_biome in [
            "the_end",
            "end_highlands",
            "end_midlands",
            "small_end_islands",
            "end_barrens",
        ] {
            assert!(
                is_known_vanilla_biome(end_biome),
                "expected fixed End biome '{end_biome}' in generated VANILLA_BIOMES"
            );
        }
    }
}
